func widgetCopy(_ key: WidgetMessage, _ language: WidgetLanguage, _ values: [String: String] = [:]) -> String {
    let template = widgetCatalogs[language]![key.rawValue]!
    // Substitute once so data can never become another placeholder or key.
    let parts = template.components(separatedBy: "{{")
    return parts[0] + parts.dropFirst().map { part in
        guard let end = part.range(of: "}}") else { return "{{" + part }
        let name = String(part[..<end.lowerBound])
        return (values[name] ?? ("{{" + name + "}}")) + part[end.upperBound...]
    }.joined()
}
